```java
import java.util.*;

public class LoopComparison {
    public static void main(String[] args) {
        // for: known iteration count
        var orders = List.of("Order1", "Order2", "Order3");
        for (int i = 0; i < orders.size(); i++) {
            System.out.println("Processing: " + orders.get(i));
        }

        // while: condition checked first (read until none left)
        Scanner scanner = new Scanner("line1\nline2");
        while (scanner.hasNextLine()) {
            System.out.println("Read: " + scanner.nextLine());
        }

        // do-while: always runs once (show menu)
        String choice;
        do {
            System.out.println("Menu: 1-Start 2-Exit");
            choice = "2"; // simulated input
        } while (!choice.equals("2"));
    }
}
```

