static Integer findFirstEven(java.util.List<Integer> nums) {
    for (int n : nums) {
        if (n % 2 == 0) return n; // exits the whole method with the result
    }
    return null; // only reached if none found
}

static void processOrders(java.util.List<String> orders) {
    for (String order : orders) {
        if (order.equals("INVALID")) continue; // skip this one
        if (order.equals("STOP")) break;        // stop processing entirely
        System.out.println("Processing: " + order);
    }
    System.out.println("Finished"); // runs after the loop (break lands here)
}
```

