import java.util.*;

public class ForEachExample {
    public static void main(String[] args) {
        var products = List.of("Laptop", "Mouse", "Keyboard");

        // for-each: clean when the index isn't needed
        for (String product : products) {
            System.out.println("Processing: " + product);
        }

        // works with arrays too
        int[] scores = {85, 90, 78, 92};
        int total = 0;
        for (int score : scores) total += score;
        System.out.println("Sum: " + total);

        // when you need the index, use a traditional for
        for (int i = 0; i < products.size(); i++) {
            System.out.println("Index " + i + " = " + products.get(i));
        }
    }
}
```

